<?php
require_once __DIR__ . '/../includes/auth.php'; requireAdmin(); $db=getDB(); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'&&verifyCsrf($_POST['csrf_token']??null)){ $action=(string)post('action'); if($action==='create'){ $name=trim((string)post('name'));$description=trim((string)post('description'));$price=(float)post('price');$days=(int)post('validity_days');$daily=(float)post('daily_profit'); if($name===''||$price<=0||$days<=0||$daily<0)$error='Enter valid package values.';else{$db->prepare('INSERT INTO packages(name,description,price,validity_days,daily_profit,total_return,status) VALUES(?,?,?,?,?,?,"active")')->execute([$name,$description,$price,$days,$daily,$daily*$days]);flash('success','Package created.');redirect(appUrl('admin/packages.php'));}} elseif($action==='toggle'){$db->prepare('UPDATE packages SET status=IF(status="active","inactive","active") WHERE id=?')->execute([(int)post('package_id')]);redirect(appUrl('admin/packages.php'));} } $packages=$db->query('SELECT * FROM packages ORDER BY price')->fetchAll(); $pageTitle='Packages';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($pageTitle) ?> - <?= e(APP_NAME) ?></title><link rel="stylesheet" href="../assets/css/style.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"></head><body><?php include __DIR__.'/_header.php'; ?><div class="page-title"><span class="eyebrow">PRODUCT CATALOG</span><h1>Packages</h1></div><?php if($error): ?><div class="alert error"><?= e($error) ?></div><?php endif; ?><?php foreach(consumeFlashes() as $f): ?><div class="alert <?= e($f['type']) ?>"><?= e($f['message']) ?></div><?php endforeach; ?><section class="panel"><h2>Add package</h2><form method="post" class="form-grid compact-form"><?= csrfField() ?><input type="hidden" name="action" value="create"><label>Name<input name="name" required></label><label>Price<input type="number" min="1" step="0.01" name="price" required></label><label>Validity days<input type="number" min="1" name="validity_days" required></label><label>Daily profit<input type="number" min="0" step="0.01" name="daily_profit" required></label><label class="span-2">Description<textarea name="description" rows="2"></textarea></label><button class="btn primary" type="submit">Create package</button></form></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>Package</th><th>Price</th><th>Daily</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($packages as $p): ?><tr><td><?= e($p['name']) ?></td><td><?= formatCurrency($p['price']) ?></td><td><?= formatCurrency($p['daily_profit']) ?></td><td><span class="badge <?= e($p['status']) ?>"><?= e(ucfirst($p['status'])) ?></span></td><td><form method="post"><?= csrfField() ?><input type="hidden" name="action" value="toggle"><input type="hidden" name="package_id" value="<?= e($p['id']) ?>"><button class="btn small ghost" type="submit">Toggle</button></form></td></tr><?php endforeach; ?></tbody></table></div></section><?php include __DIR__.'/_footer.php'; ?></body></html>
